window.LG4_AREAS = [{"id": "lg4-3-1", "name": "Archery ranges", "section": "3.1", "page": 15, "tables": ["Class       Horizontal                  Vertical illuminance on target                Colour\n           illuminance              Outdoor                    Indoor               rendering\n         shooting zone                              25m dist. 50m dist.               index\n        Eav (lx)   Emin/Eav   Evav (lx) Evmin/Evav Evav (lx)   Evav (lx) Evmin/Evav\nI        200         0.5       750        0.8       1000       2000        0.8        60\nII       200         0.5       750        0.8       1000       2000        0.8        60\nIII      200         0.5       750        0.8       1000       2000        0.8        60"], "notes": [], "installation": "Archery ranges generally accommodate target distances of 30–90 m at 10 m increments. The lighting must enable the targets to be easily seen at each distance and allow archers to see the position of each arrow in the target. Sufficient light is also needed in the shooting zone for nocking, making bow adjustments and for general safety and movement. It is also important to provide general illumination of the ground between the shooting line and the targets to assist in judging distances. Floodlighting positions should be located behind the shooting line and aimed directly at the furthermost targets. It is usual for several shooting positions to converge onto a single target. If adequate illumination of the furthermost targets is provided, then sufficient illumination of the nearer targets and ground to the shooting line is normally achieved. Whether or not the main lighting produces sufficient spill light to illuminate the shooting zone will depend upon the type of lighting system used. Glare should not cause a problem for archers when they are shooting at targets. After retrieval of the arrows, however, glare may be experienced when the archers are returning to the shooting line. Indoor archery generally takes place in large multipurpose sports halls or arenas (see sections 4 and 6).", "structuredTables": [{"columns": ["Parameter", "Class I", "Class II", "Class III"], "rows": [["Shooting zone · Horizontal illuminance · Eav (lux)", "200", "200", "200"], ["Shooting zone · Uniformity · Emin/Eav", "0.5", "0.5", "0.5"], ["Outdoor target · Vertical illuminance · Evav (lux)", "750", "750", "750"], ["Outdoor target · Vertical uniformity · Evmin/Evav", "0.8", "0.8", "0.8"], ["Indoor target at 25 m · Vertical illuminance · Evav (lux)", "1000", "1000", "1000"], ["Indoor target at 50 m · Vertical illuminance · Evav (lux)", "2000", "2000", "2000"], ["Indoor target · Vertical uniformity · Evmin/Evav", "0.8", "0.8", "0.8"], ["Colour rendering index · Ra", "60", "60", "60"]]}]}, {"id": "lg4-3-2", "name": "Athletics", "section": "3.2", "page": 15, "tables": ["Class                        Horizontal illuminance                                       Colour             Glare\n                   Indoor athletics            Outdoor athletics                        rendering            rating\n                Eav (lx)      Emin/Eav       Eav (lx)     Emin/Eav                        index\nI                 500                0.7               500                 0.7               60                  50\nII                300                0.6               200                 0.7               60                  50\nIII               200                0.5               100(note 3)         0.5               20                  55"], "notes": ["Note 1: Glare should be controlled by careful positioning of luminaires, over the pole vault area for instance.", "Note 2: The vertical illuminance at the finishing line should be at least 1000 lux for photo-finish equipment.", "Note 3: For outdoor tracks (class III) the level of horizontal illuminance can be reduced to 50 lux for jogging (see section 5)."], "installation": "Most athletics events take place in a stadium or indoor arena that is likely to be lit to a standard that simultaneously satisfies the illuminance requirements both for track events and for those areas bounded by the track that are used for field events (see sections 5 and 6). Athletics encompasses such events as discuss and hammer throwing, shot put, high jump, hurdling, long jump, javelin, pole vault, running, triple jump etc, and takes place either outdoors or indoors. Indoor events that do not use the running track are still referred to as field events.", "structuredTables": [{"columns": ["Parameter", "Class I", "Class II", "Class III"], "rows": [["Indoor · Horizontal illuminance · Eav (lux)", "500", "300", "200"], ["Indoor · Uniformity · Emin/Eav", "0.7", "0.6", "0.5"], ["Outdoor · Horizontal illuminance · Eav (lux)", "500", "200", "100(note 3)"], ["Outdoor · Uniformity · Emin/Eav", "0.7", "0.7", "0.5"], ["Colour rendering index · Ra", "60", "60", "20"], ["Glare rating · GR", "50", "50", "55"]]}]}, {"id": "lg4-3-3", "name": "Badminton (indoor)", "section": "3.3", "page": 16, "tables": ["Class                                     Horizontal illuminance                              Colour rendering\n                               Eav (lx)                       Emin/Eav                             index\nI                               750                                  0.7                                60\nII                              500                                  0.7                                60\nIII                             300                                  0.7                                20"], "notes": ["Note 1: No luminaires should be positioned in that part of the ceiling directly above the playing area.", "Note 2: The reflectance values of court-side fabrics should not be greater than 0.5 for walls and 0.6–0.9 for ceilings. Background colours of blue and green are preferable.", "Note 3: The Badminton Federation may require particular specifications for competition and international provision."], "installation": "As the shuttle may move at relatively high speeds over the net, it is essential for players to be able to follow the flight of the shuttle, seen in contrast against the dark background, without being troubled by glare or having their concentration adversely influenced by high-intensity light sources in the vicinity of sight lines. For optimum visual conditions the shuttle is more easily seen when illuminated against a dark background. The path of the shuttle during play is often high above the net and therefore sufficient vertical illuminance must be provided. Badminton is typically played either in a dedicated facility or in a multipurpose sports hall (see section 4).", "structuredTables": [{"columns": ["Parameter", "Class I", "Class II", "Class III"], "rows": [["Horizontal illuminance · Eav (lux)", "750", "500", "300"], ["Uniformity · Emin/Eav", "0.7", "0.7", "0.7"], ["Colour rendering index · Ra", "60", "60", "20"]]}]}, {"id": "lg4-3-4", "name": "Baseball", "section": "3.4", "page": 16, "tables": ["Class                            Horizontal illuminance                                Glare            Colour\n                           Infield                     Outfield                        rating         rendering\n                  Eav (lx)         Emin/Eav     Eav (lx)      Emin/Eav                                  index\nI                  750               0.7              500               0.5               50               60\nII                 500               0.7              300               0.5               50               60\nIII                300               0.5              200               0.3               55               20"], "notes": [], "installation": "A fast sport when the ball is pitched and hit, baseball requires high levels of illumination to enable the action and flight of the ball to be followed. Most of the fast action takes place in the regulation-sized infield, which will require a significantly greater illuminance and overall uniformity than the larger outfield (the area of which may vary). Floodlighting must minimise shadowing and achieve good modelling of players while providing control of glare to players, officials and spectators.", "structuredTables": [{"columns": ["Parameter", "Class I", "Class II", "Class III"], "rows": [["Infield · Horizontal illuminance · Eav (lux)", "750", "500", "300"], ["Infield · Uniformity · Emin/Eav", "0.7", "0.7", "0.5"], ["Outfield · Horizontal illuminance · Eav (lux)", "500", "300", "200"], ["Outfield · Uniformity · Emin/Eav", "0.5", "0.5", "0.3"], ["Glare rating · GR", "50", "50", "55"], ["Colour rendering index · Ra", "60", "60", "20"]]}]}, {"id": "lg4-3-5", "name": "Basketball", "section": "3.5", "page": 17, "tables": ["Class                         Horizontal illuminance                                     Colour          Glare\n                     Outdoor courts              Indoor courts(note 1)                 rendering         rating\n                Eav (lx)      Emin/Eav       Eav (lx)      Emin/Eav                      index\nI                  -                 -                750                0.7                60                  -\nII                 -                 -                500                0.7                60                  -\nIII               75                0.5               200                0.5                20              55(note 2)"], "notes": ["Note 1: The reflectance values of court-side fabrics should not be greater than 0.5 for walls and 0.6–0.9 for ceilings. Background colours of blue and green are preferable.", "Note 2: Outdoor courts only."], "installation": "Basketball is played indoors at all levels of competition and outdoors at a primarily recreational level. The lighting should enable players to follow the movement of the ball while being able accurately to discern the court markings at floor level. Good vertical illuminance on a fast-moving ball is important so as to prevent apparent changes in ball speed. Basketball is typically played in a dedicated facility, a multipurpose sports hall (see section 4) or a multipurpose outdoor court. Luminaires should be positioned so as to cause a minimum of visual distraction to players, although the total elimination of glare is almost impossible. In order to reduce glare in interior installations it is particularly important to control the fabric reflectance of the ceiling so that, taken as a whole, the luminance contrast of the ceiling (against which the luminaires will be viewed) will not be excessive. Their relatively rapid start, colour rendering and correlated colour temperature characteristics make tubular fluorescent lamps particularly suitable for illuminating indoor basketball courts. For indoor courts on which different classes of competition may be played, it may be useful to consider dimming when lower competition levels are being staged.", "structuredTables": [{"columns": ["Parameter", "Class I", "Class II", "Class III"], "rows": [["Outdoor · Horizontal illuminance · Eav (lux)", "-", "-", "75"], ["Outdoor · Uniformity · Emin/Eav", "-", "-", "0.5"], ["Indoor · Horizontal illuminance · Eav (lux)", "750", "500", "200"], ["Indoor · Uniformity · Emin/Eav", "0.7", "0.7", "0.5"], ["Colour rendering index · Ra", "60", "60", "20"], ["Glare rating · GR", "-", "-", "55(note 2)"]]}]}, {"id": "lg4-3-6", "name": "Bowls (indoor)", "section": "3.6", "page": 17, "tables": ["Class                         Horizontal illuminance                   Colour rendering\n                       Eav (lx)                    Emin/Eav                 index\nI                       500                          0.8                      60\nII                      500                          0.8                      60\nIII                     300                          0.5                      20"], "notes": [], "installation": "Indoor greens are normally divided into several parallel 5 m lanes. Visual requirements are for the player to be able to see the jack and the lie of the woods around it and to follow the run of the live wood. Although the speed of the wood is slow, as the viewing distance is high, sufficient illumination must be provided for the position of the woods to be visible at the end of the lane. Because of the large open area, the uniformity of the brightness of the green is very important. This will be influenced not only by the lighting system but also by the material of the green itself. This generally has a nap that will give a different brightness impression when viewed from different directions.", "structuredTables": [{"columns": ["Parameter", "Class I", "Class II", "Class III"], "rows": [["Horizontal illuminance · Eav (lux)", "500", "500", "300"], ["Uniformity · Emin/Eav", "0.8", "0.8", "0.5"], ["Colour rendering index · Ra", "60", "60", "20"]]}]}, {"id": "lg4-3-7", "name": "Bowls (outdoor)", "section": "3.7", "page": 18, "tables": ["Class             Horizontal illuminance                      Glare    Colour rendering\n                Eav (lx)            Emin/Eav                  rating        index\nI                200                   0.7                     50             60\nII               200                   0.7                     50             60\nIII              100                   0.7                     55             20"], "notes": [], "installation": "A player must be able to see the jack and the lie of the woods around it and to follow the run of the live wood. The judgement of the players must not be impaired by harsh shadows, even when both jack and woods are closely clustered. The bowling green should appear to be uniformly bright from all playing ends while maintaining low glare to participants and spectators. The green should be illuminated from floodlights located either at the four corners or at a minimum of two opposite sides. A high degree of uniformity is necessary with the light reaching all points of the green from at least two directions. This will soften the shadows produced by the woods. The line of sight is a little below the horizontal, enabling glare to be controlled by careful selection of mounting height and aiming floodlights within near parts of the green.", "structuredTables": [{"columns": ["Parameter", "Class I", "Class II", "Class III"], "rows": [["Horizontal illuminance · Eav (lux)", "200", "200", "100"], ["Uniformity · Emin/Eav", "0.7", "0.7", "0.7"], ["Glare rating · GR", "50", "50", "55"], ["Colour rendering index · Ra", "60", "60", "20"]]}]}, {"id": "lg4-3-8", "name": "Bowling (nine or ten pin)", "section": "3.8", "page": 18, "tables": ["Class                Horizontal illuminance                     Vertical illuminance                     Colour\n                         (approach lanes)                               (pins)                         rendering\n                     Eav (lx)         Emin/Eav                Evav (lx)        Evmin/Evav                index\nI                     200                  0.5                  500                   0.8                   60\nII                    200                  0.5                  500                   0.8                   60\nIII                   200                  0.5                  500                   0.8                   60"], "notes": [], "installation": "A player must be able clearly to see the positions of the pins on the pin deck and follow the ball’s movement down the lane. Each lane should appear uniform while maintaining low glare to both the players and spectators without casting major shadows in any direction. Illumination of the lane area is usually provided by a series of ceiling-mounted luminaires, usually behind a saw-toothed ceiling grid providing general illumination or recessed overhead lighting, both of which ensure that shadows are not cast on the lanes. For competition bowling especially, when players ‘exchange’ lanes, lane lighting should not offer any advantage to players on one lane over any immediate adjoining lane. Lighting immediately over each set of pins should be of a higher level than that over the lanes and should not cast shadows. The viewing area is usually situated immediately behind and above the lane area. No shadows or stray light should encroach from the viewing area into the lane area.", "structuredTables": [{"columns": ["Parameter", "Class I", "Class II", "Class III"], "rows": [["Approach lanes · Horizontal illuminance · Eav (lux)", "200", "200", "200"], ["Approach lanes · Uniformity · Emin/Eav", "0.5", "0.5", "0.5"], ["Pins · Vertical illuminance · Evav (lux)", "500", "500", "500"], ["Pins · Vertical uniformity · Evmin/Evav", "0.8", "0.8", "0.8"], ["Colour rendering index · Ra", "60", "60", "60"]]}]}, {"id": "lg4-3-9", "name": "Boxing", "section": "3.9", "page": 19, "tables": ["Class                                 Horizontal illuminance                                   Colour rendering\n                               Eav (lx)                    Emin/Eav                                 index\nI                               2000                                0.8                                80\nII                              1000                                0.8                                80\nIII                              500                                0.5                                60"], "notes": ["Note 1: Vertical illuminance should be at least 50% of horizontal illuminance."], "installation": "Action is rapid and takes place at close quarters. Referees, judges, spectators and participants need good visibility from all directions. For supervised training it may be possible to use the general lighting installation. For competition standards the lighting installations should be provided from a ceiling-mounted array of luminaires positioned to provide uniform illumination. Although horizontal illuminances over the boxing ring are high, the corresponding values on vertical planes can be relatively low (see note 1). The requirements of distant viewing spectators should be considered.", "structuredTables": [{"columns": ["Parameter", "Class I", "Class II", "Class III"], "rows": [["Horizontal illuminance · Eav (lux)", "2000", "1000", "500"], ["Uniformity · Emin/Eav", "0.8", "0.8", "0.5"], ["Colour rendering index · Ra", "80", "80", "60"]]}]}, {"id": "lg4-3-10", "name": "Canoe slalom", "section": "3.10", "page": 19, "tables": ["Class                     Horizontal illuminance                                       Glare             Colour\n                  Water course         Access and removal points                       rating          rendering\n             Eav (lx)      Emin/Eav       Eav (lx)    Emin/Eav                                           index\nI              200                0.5                50                0.5                50                60\nII             100                0.5                50                0.5                50                60\nIII             50                0.5                50                0.5                55                20"], "notes": ["Note 1: Safety lighting (see section 2.8.2.1). Lighting level for the safe stopping of an event is 10% of that for the appropriate class for a minimum of 120 s.", "Note 2: The calculation reference plane is at water’s edge – finished level per course section.", "Note 3: These lighting specifications may also be utilised for white water rafting."], "installation": "Canoe slalom courses are formed from very fast-flowing turbulent water with access and removal points at each end of the course. This turbulence forms a non-level reference surface. Although the course direction is predominantly downhill it is necessary for participants to paddle against the direction of flow so as to negotiate scoring gates hanging above the water. Lighting should be bi-directional with masts located along both banks of the water and directed predominantly down the course axis. Direct glare to participants should be restricted, but it will not be possible to prevent high-luminance images of the floodlights in the water. In the case of power failure it should be assumed that canoeists will be in the water. Safety lighting should be provided to enable the event to be stopped without risk to participants.", "structuredTables": [{"columns": ["Parameter", "Class I", "Class II", "Class III"], "rows": [["Water course · Horizontal illuminance · Eav (lux)", "200", "100", "50"], ["Water course · Uniformity · Emin/Eav", "0.5", "0.5", "0.5"], ["Access / removal points · Horizontal illuminance · Eav (lux)", "50", "50", "50"], ["Access / removal points · Uniformity · Emin/Eav", "0.5", "0.5", "0.5"], ["Glare rating · GR", "50", "50", "55"], ["Colour rendering index · Ra", "60", "60", "20"]]}]}, {"id": "lg4-3-11", "name": "Cricket (outdoor)", "section": "3.11", "page": 19, "tables": ["Class                   Horizontal illuminance                        Glare         Colour\n         Infield (wicket square)                Outfield              rating      rendering\n          Eav (lx)       Emin/Eav       Eav (lx)        Emin/Eav                    index\nI          750             0.7            500             0.5          50              60\nII         500             0.7            300             0.5          50              60\nIII        300             0.5            200             0.3          55              20"], "notes": [], "installation": "The development of day/night cricket almost invariably involves starting a game in natural daylight but carrying it on through dusk until (depending upon several factors including the time of the year) total darkness prevails. There is therefore a requirement for some form of floodlighting to be installed.", "structuredTables": [{"columns": ["Parameter", "Class I", "Class II", "Class III"], "rows": [["Infield / wicket square · Horizontal illuminance · Eav (lux)", "750", "500", "300"], ["Infield / wicket square · Uniformity · Emin/Eav", "0.7", "0.7", "0.5"], ["Outfield · Horizontal illuminance · Eav (lux)", "500", "300", "200"], ["Outfield · Uniformity · Emin/Eav", "0.5", "0.5", "0.3"], ["Glare rating · GR", "50", "50", "55"], ["Colour rendering index · Ra", "60", "60", "20"]]}]}, {"id": "lg4-3-12", "name": "Cricket (indoor)", "section": "3.12", "page": 20, "tables": ["Class                          Horizontal illuminance                       Colour rendering\n                        Eav (lx)                    Emin/Eav                     index\nI                         750                           0.7                       60\nII                        500                           0.7                       60\nIII                       300                           0.7                       20"], "notes": [], "installation": "Action is rapid and can take place at close quarters. Umpires, spectators and players need good visibility from all directions to enable the movement of the ball to be followed. The lighting installations should be provided from ceiling-mounted luminaires positioned to provide uniform illumination without glare. Where protective netting is required, this should ideally be installed 1 m below the luminaires. Glare cannot be eliminated completely as players must look upwards, but can be controlled by diffusing the light output and reducing the contrast between the luminaire and the ceiling.", "structuredTables": [{"columns": ["Parameter", "Class I", "Class II", "Class III"], "rows": [["Horizontal illuminance · Eav (lux)", "750", "500", "300"], ["Uniformity · Emin/Eav", "0.7", "0.7", "0.7"], ["Colour rendering index · Ra", "60", "60", "20"]]}]}, {"id": "lg4-3-13", "name": "Cricket (indoor training nets)", "section": "3.13", "page": 20, "tables": ["Class                                Horizontal illuminance                                     Colour rendering\n                              Eav (lx)                    Emin/Eav                                   index\nI                              1500                                 0.8                                60\nII                             1000                                 0.8                                60\nIII                             750                                 0.8                                20"], "notes": [], "installation": "Participants must be able to concentrate in safety without distraction from the lighting installation. The bowler and batsman must be able to follow the movement of the ball during its flight. The bowler must have a clear view of the wicket and the batsman must be able to study the bowler’s action and run up.", "structuredTables": [{"columns": ["Parameter", "Class I", "Class II", "Class III"], "rows": [["Horizontal illuminance · Eav (lux)", "1500", "1000", "750"], ["Uniformity · Emin/Eav", "0.8", "0.8", "0.8"], ["Colour rendering index · Ra", "60", "60", "20"]]}]}, {"id": "lg4-3-14", "name": "Curling", "section": "3.14", "page": 21, "tables": ["Class               Horizontal illuminance                     Horizontal illuminance                    Colour\n                             ‘House’                                    Rink                           rendering\n                    Eav (lx)         Emin/Eav                  Eav (lx)        Emin/Eav                  index\nI                     300                  0.7                  200                   0.7                   60\nII                    300                  0.7                  200                   0.7                   60\nIII                   300                  0.7                  200                   0.7                   60"], "notes": [], "installation": "Curling can be played either outdoors or indoors. Artificial lighting may therefore be from floodlights on poles (outdoors) or overhead luminaires (indoors). Lighting should preferably be placed to the side of the lanes. In the case of outdoor facilities, several lanes may be illuminated from poles placed on either side. As the participants’ viewing distance is long, sufficient illumination must be provided for the position of the stones to be visible at the end of the rink. A higher illuminance is recommended for the ‘house’. The ice acts as a good diffuse reflector, thus helping to ensure that there are no strongly marked patterns of light that could distract from the game. Glare control is relatively easy to achieve as the main direction of view is below the horizontal plane. Care needs to be taken in the selection and location of luminaires so that direct glare is minimised. Suitable louvres and screening can prove effective in limiting the glare. The ceiling reflectance needs to be high (at least 60%) to reduce the luminance contrast when compared with the ice rink surface.", "structuredTables": [{"columns": ["Parameter", "Class I", "Class II", "Class III"], "rows": [["House · Horizontal illuminance · Eav (lux)", "300", "300", "300"], ["House · Uniformity · Emin/Eav", "0.7", "0.7", "0.7"], ["Rink · Horizontal illuminance · Eav (lux)", "200", "200", "200"], ["Rink · Uniformity · Emin/Eav", "0.7", "0.7", "0.7"], ["Colour rendering index · Ra", "60", "60", "60"]]}]}, {"id": "lg4-3-15", "name": "Cycle racing (track)", "section": "3.15", "page": 21, "tables": ["Class                       Horizontal illuminance                                     Glare             Colour\n                  Indoor tracks                Outdoor tracks                          rating          rendering\n             Eav (lx)        Emin/Eav       Eav (lx)     Emin/Eav                                        index\nI           750                   0.7               500                0.7                 50               60\nII          500                   0.7               300                0.7                 50               60\nIII         200                   0.5               100                0.5                 55               20"], "notes": ["Note 1: Illuminance is taken on the track surface, whether it be horizontal or inclined.", "Note 2: Vertical illuminance at the finish line should be 1000 lux to aid the use of photo-finish equipment.", "Note 3: Safety lighting (see section 2.8.2.1). The lighting level for the safe stopping of an event is 10% of that for the appropriate class for a minimum of 60 s."], "installation": "The ergonomics of the normal riding position are such that the cyclists look straight ahead and slightly downwards. It is essential therefore that the reflectance of the track is not excessive; values of 0.2–0.4 are generally considered acceptable. As spectators are required to view action on distant sections of the track, it is important for illuminances to be adequate without creating unwanted glare. It is necessary to maintain good lighting uniformity and avoid the creation of black spots that may lead to accidents when competitors are fast-moving. If the central area of the velodrome is used for hospitality, then it is important to prevent the ambient lighting of the central area from impinging onto the track, as this may be disturbing for the competitors.", "structuredTables": [{"columns": ["Parameter", "Class I", "Class II", "Class III"], "rows": [["Indoor track · Horizontal illuminance · Eav (lux)", "750", "500", "200"], ["Indoor track · Uniformity · Emin/Eav", "0.7", "0.7", "0.5"], ["Outdoor track · Horizontal illuminance · Eav (lux)", "500", "300", "100"], ["Outdoor track · Uniformity · Emin/Eav", "0.7", "0.7", "0.5"], ["Glare rating · GR", "50", "50", "55"], ["Colour rendering index · Ra", "60", "60", "20"]]}]}, {"id": "lg4-3-16", "name": "Dancing/aerobics/keep fit", "section": "3.16", "page": 22, "tables": ["Class                          Horizontal illuminance                   Colour rendering\n                        Eav (lx)                    Emin/Eav                 index\nI                         500                         0.7                       60\nII                        300                         0.6                       60\nIII                       200                         0.5                       20"], "notes": [], "installation": "Participants must be able to concentrate on their movement and rhythm without the distraction of the lighting installation. This activity involves various positions and speed of movement around the dance floor or activity area. The lighting installation should be provided from a ceiling-mounted array of luminaires positioned to provide uniform illumination. During the design process, the type of light source and the positioning of the luminaires should be selected to reduce the possibility of glare. Dance/keep-fit is typically performed in a multipurpose sports hall (see section 4).", "structuredTables": [{"columns": ["Parameter", "Class I", "Class II", "Class III"], "rows": [["Horizontal illuminance · Eav (lux)", "500", "300", "200"], ["Uniformity · Emin/Eav", "0.7", "0.6", "0.5"], ["Colour rendering index · Ra", "60", "60", "20"]]}]}, {"id": "lg4-3-17", "name": "Darts", "section": "3.17", "page": 22, "tables": ["Class            Horizontal illuminance      Vertical illuminance             Colour\n                      (over oche)               (over target)               rendering\n                        Eav (lx)                    Evav (lx)                 index\nI                         200                         750                       60\nII                        100                         500                       60\nIII                        50                         300                       20"], "notes": [], "installation": "Participants must be able to concentrate on their throwing in safety without distraction from the lighting installation. Illumination of the dart board is usually provided by an overhead pointsource luminaire of sufficient beam width to achieve uniform illumination over the target. It is essential that the target lighting should enable players to identify clearly all scoring segments of the dartboard. Separate illumination should be provided over the adjacent scoreboard and oche (throwing line at 3–4 m from the dartboard).", "structuredTables": [{"columns": ["Parameter", "Class I", "Class II", "Class III"], "rows": [["Oche · Horizontal illuminance · Eav (lux)", "200", "100", "50"], ["Target · Vertical illuminance · Evav (lux)", "750", "500", "300"], ["Colour rendering index · Ra", "60", "60", "20"]]}]}, {"id": "lg4-3-18", "name": "Equestrian sports (indoor and outdoor)", "section": "3.18", "page": 22, "tables": ["Class                       Horizontal illuminance                                     Glare              Colour\n                      Indoor                        Outdoor                            rating           rendering\n             Eav (lx)        Emin/Eav       Eav (lx)      Emin/Eav                                        index\nI          500                    0.7               500                0.7                50                 60\nII         300                    0.6               200                0.5                55                 60\nIII        200                    0.5               100                0.5                55                 20"], "notes": ["Note 1: Safety lighting (see section 2.8.2.1). Lighting level for the safe stopping of an event is 5% of that for the appropriate class for a minimum of 120 s."], "installation": "This section deals with the lighting of areas used for showjumping, dressage, schooling and the practice and training of horses. Major showjumping and dressage events are normally held in sports stadia or indoor arenas often equipped with facilities for television broadcasting (see sections 5, 6 and 7). Lighting is provided to enable the safe movement of both horse and rider appropriate to the standard of participation. The action of both must be clearly seen by spectators, officials and trainers. The lighting installation should provide illumination over the total floor area. Shadows should be minimised as these may distract the horses. In many cases, the most cost-effective lighting solution is a side-lighting system. Most purpose-built arenas are rectangular in design, although the overall dimensions may vary considerably. The smallest arena size suitable for dressage tests is 20 x 40 m while a full showjumping round will require a minimum of 80 x 210 m. A suitable area for schooling would be approximately 25 x 65 m. The lighting must be adequate to enable the safe progress of both horse and rider over the jumps and to discern the finer points of dressage. It is important that a high degree of lighting uniformity is achieved with minimal shadowing around showjumping fences.", "structuredTables": [{"columns": ["Parameter", "Class I", "Class II", "Class III"], "rows": [["Indoor · Horizontal illuminance · Eav (lux)", "500", "300", "200"], ["Indoor · Uniformity · Emin/Eav", "0.7", "0.6", "0.5"], ["Outdoor · Horizontal illuminance · Eav (lux)", "500", "200", "100"], ["Outdoor · Uniformity · Emin/Eav", "0.7", "0.5", "0.5"], ["Glare rating · GR", "50", "55", "55"], ["Colour rendering index · Ra", "60", "60", "20"]]}]}, {"id": "lg4-3-19", "name": "Fencing", "section": "3.19", "page": 23, "tables": ["Class               Horizontal illuminance                      Vertical illuminance                      Colour\n                             (on piste)                           (along piste axis)                    rendering\n                    Eav (lx)            Emin/Eav              Evav (lx)        Evmin/Evav                 index\nI                     750                   0.8                  500                   0.7                   60\nII                    500                   0.8                  300                   0.7                   60\nIII                   200                   0.8                  200                   0.7                   20"], "notes": [], "installation": "The speed of action in fencing is generally extremely fast. The activity involves varying positions and speed of movement on the floor. Participants must be able quickly to discern the opponent’s movements, gauge or make attacks and perform movements without the effects of glare from the lighting installation. The contrast between the ceiling and the luminaires should be low to eliminate distraction. The lighting should be provided from a ceiling-mounted array of luminaires positioned to provide uniform illumination over the piste. Fencing is typically played in a multipurpose sports hall (see section 4).", "structuredTables": [{"columns": ["Parameter", "Class I", "Class II", "Class III"], "rows": [["Piste · Horizontal illuminance · Eav (lux)", "750", "500", "200"], ["Piste · Uniformity · Emin/Eav", "0.8", "0.8", "0.8"], ["Along piste axis · Vertical illuminance · Evav (lux)", "500", "300", "200"], ["Along piste axis · Vertical uniformity · Evmin/Evav", "0.7", "0.7", "0.7"], ["Colour rendering index · Ra", "60", "60", "20"]]}]}, {"id": "lg4-3-20", "name": "Five-a-side football (indoor)", "section": "3.20", "page": 23, "tables": ["Class                                 Horizontal illuminance                                   Colour rendering\n                               Eav (lx)                    Emin/Eav                                 index\nI                               750                                 0.7                                 60\nII                              500                                 0.7                                 60\nIII                             200                                 0.5                                 20"], "notes": [], "installation": "Five-a-side football is usually played in multi-use sports halls. Some competitive events plus a similar six-a-side version are played in large halls or small arenas, but in all cases the requirements are similar. Players must be able to follow movement of both the ball and other players. Many five-a-side courts are defined on a multi-use playing surface which may also be marked out for other sports such as basketball or badminton. The lighting must enable players easily to identify the court markings. Suitable illumination can usually be provided by luminaires fixed above the playing area and spaced to meet the uniformity requirements. Although the play generally takes place at low level there is a risk of deflection of the ball to high levels. Luminaires may therefore require protection against ball impact. Glare should be minimised by controlling luminance to lower the brightness contrast between the luminaires and the ceiling.", "structuredTables": [{"columns": ["Parameter", "Class I", "Class II", "Class III"], "rows": [["Horizontal illuminance · Eav (lux)", "750", "500", "200"], ["Uniformity · Emin/Eav", "0.7", "0.7", "0.5"], ["Colour rendering index · Ra", "60", "60", "20"]]}]}, {"id": "lg4-3-21", "name": "Fitness training", "section": "3.21", "page": 23, "tables": ["Horizontal illuminance    Uniformity Emin/Eav    Colour rendering index\n500 lux                   0.8                    60"], "notes": [], "installation": "Control glare throughout the training area. Supplement the general lighting where equipment or difficult activities require better visibility.", "structuredTables": [{"columns": ["Parameter", "Requirement"], "rows": [["Horizontal illuminance · Eav (lux)", "500"], ["Uniformity · Emin/Eav", "0.8"], ["Colour rendering index · Ra", "60"]]}]}, {"id": "lg4-3-22", "name": "Football (American)", "section": "3.22", "page": 24, "tables": ["Class                    Horizontal illuminance                           Glare              Colour rendering\n                       Eav (lx)            Emin/Eav                       rating                  index\nI                         500                     0.7                       50                         60\nII                        200                     0.6                       50                         60\nIII                       75                      0.5                       55                         20"], "notes": ["Note 1: American football leagues will require particular lighting specifications for competition and stadia provision."], "installation": "The lighting should provide uniform illumination over the long, narrow pitch, ensuring that the full flight of the ball is visible while providing good viewing conditions for players, officials and spectators at all times. For competitions, the lighting requirements will probably be dictated by the viewing requirements of spectators, which in turn are related to the viewing conditions and spectator capacity of the sports ground (see section 5.2.2). Various lighting systems may be suitable for American football grounds and stadia (see sections 5.1 and 5.2). Owing to the possibility of large spectator attendance, it is important to consider the requirements for emergency lighting (see section 2.8). In the provision of any lighting system, thought should be given to reducing the visual obstruction of the event for spectators wherever possible. Care should be taken to ensure that shadows are not cast onto the pitch from floodlights located behind grandstand rooflines. Obtrusive light limitations will need to be considered if planning consent is required (see section 2.10.1).", "structuredTables": [{"columns": ["Parameter", "Class I", "Class II", "Class III"], "rows": [["Horizontal illuminance · Eav (lux)", "500", "200", "75"], ["Uniformity · Emin/Eav", "0.7", "0.6", "0.5"], ["Glare rating · GR", "50", "50", "55"], ["Colour rendering index · Ra", "60", "60", "20"]]}]}, {"id": "lg4-3-23", "name": "Football (association)", "section": "3.23", "page": 24, "tables": ["Class                   Horizontal illuminance(note 2)                    Glare              Colour rendering\n                     Eav (lx)             Emin/Eav                        rating                  index\nI                      500                        0.7                       50                        60\nII                     200                        0.6                       50                        60\nIII                    75                         0.5                       55                        20"], "notes": ["Note 1: The Football Association, Football League and Premier League will require particular lighting specifications in accordance with UEFA and FIFA criteria for competition and stadia provision.", "Note 2: Determination of maintained illuminance (see appendix 1 footnote)"], "installation": "Lighting should provide uniform illumination over the pitch, appropriate for the proposed grade of supervision or league status. For non-league play and supervised training, a relatively low illuminance and uniformity may be acceptable. For competition matches the lighting requirements will probably be dictated by the viewing requirements of spectators, which are in turn related to the viewing conditions and spectator capacity (see section 5.2.2). Particular attention should be paid to providing low glare and uniform lighting within goalmouth areas.", "structuredTables": [{"columns": ["Parameter", "Class I", "Class II", "Class III"], "rows": [["Horizontal illuminance · Eav (lux)", "500", "200", "75"], ["Uniformity · Emin/Eav", "0.7", "0.6", "0.5"], ["Glare rating · GR", "50", "50", "55"], ["Colour rendering index · Ra", "60", "60", "20"]]}]}, {"id": "lg4-3-24", "name": "Football (Gaelic)", "section": "3.24", "page": 25, "tables": ["Class                  Horizontal illuminance                             Glare              Colour rendering\n                     Eav (lx)            Emin/Eav                         rating                  index\nI                     500                 0.7                     50                     60\nII                    200                 0.6                     50                     60\nIII                   75                  0.5                     55                     20"], "notes": ["Note 1: The Gaelic Athletic Association may require particular specifications for competition and international provision."], "installation": "Lighting should provide uniform illumination over the pitch, appropriate for the proposed grade of competition. The lighting should ensure that the full flight of the ball is visible while providing good viewing conditions for players, officials and spectators. For competitions, the lighting requirements will probably be dictated by the viewing requirements of spectators, which are in turn related to the viewing conditions and spectator capacity (see section 5.2.2). Particular attention should be paid to providing low glare and uniform lighting within goalmouth areas. This is to ensure good visual conditions for goalkeepers relative to set plays. To ensure good viewing conditions for goalkeepers, lighting masts should not be located in line with the goal-line axes (±10°). Various lighting systems may be suitable for Gaelic football grounds and stadia (see sections 5.1 and 5.2). In the provision of any lighting system, thought should be given to reducing the visual obstruction of the event for spectators wherever possible. Care should be taken to ensure that shadows are not cast onto the pitch from floodlights located behind grandstand roof lines. Owing to the possibility of large spectator attendance, it is important to consider the requirements for emergency lighting (see section 2.8). Obtrusive light limitations will need to be considered if planning consent is required (see section 2.10.1).", "structuredTables": [{"columns": ["Parameter", "Class I", "Class II", "Class III"], "rows": [["Horizontal illuminance · Eav (lux)", "500", "200", "75"], ["Uniformity · Emin/Eav", "0.7", "0.6", "0.5"], ["Glare rating · GR", "50", "50", "55"], ["Colour rendering index · Ra", "60", "60", "20"]]}]}, {"id": "lg4-3-25", "name": "Golf courses", "section": "3.25", "page": 25, "tables": ["Class       Horizontal      Horizontal            Vertical            Horizontal    Glare Colour\n           illuminance illuminance on illuminance on                 illuminance    rating rendering\n              on tees        fairways(notes 2/3) fairways(notes 1/2)  on greens              index\n         Eav (lx) Emin/Eav Eav (lx) Emin/Eav Evav (lx) Evmin/Evav Eav (lx) Emin/Eav\nI       200          0.7       100        0.5       200         -        250        0.7       50   60\nII      100          0.7       75         0.5       150         -        150        0.7       50   60"], "notes": ["Note 1: Vertical illuminance at 5 m above the fairway.", "Note 2: Semi-rough ground to be included.", "Note 3: Not applicable over water obstacles and features.", "Note 4: The lighting levels stated do not relate to requirements for general course maintenance."], "installation": "While most golf course lighting is restricted to practice areas and putting greens, there is growing interest in lighting par-three and shortened courses for night play. The principal requirement in all cases is to ensure that environmental impact is minimised while creating a pleasant night-time appearance with good viewing conditions for golfers.", "structuredTables": [{"columns": ["Parameter", "Class I", "Class II"], "rows": [["Tees · Horizontal illuminance · Eav (lux)", "200", "100"], ["Tees · Uniformity · Emin/Eav", "0.7", "0.7"], ["Fairways · Horizontal illuminance · Eav (lux)", "100", "75"], ["Fairways · Uniformity · Emin/Eav", "0.5", "0.5"], ["Fairways · Vertical illuminance · Evav (lux)", "200", "150"], ["Fairways · Vertical uniformity · Evmin/Evav", "-", "-"], ["Greens · Horizontal illuminance · Eav (lux)", "250", "150"], ["Greens · Uniformity · Emin/Eav", "0.7", "0.7"], ["Glare rating · GR", "50", "50"], ["Colour rendering index · Ra", "60", "60"]]}]}, {"id": "lg4-3-26", "name": "Golf driving ranges", "section": "3.26", "page": 27, "tables": ["Class             Horizontal illuminance         Vertical illuminance on   Colour\n                         (on tee)              distance marker (+1m AGL) rendering\n                Eav (lx)            Emin/Eav              Evav (lx)        index\nIII              100                  0.8                 50                20"], "notes": [], "installation": "The distance markers must be clearly visible and the player must be able to follow the flight of the ball. While the tee areas will require separate illumination, there should be general illumination of the full length of the golf range surface. End-range lighting systems have primarily been utilised to illuminate golf ranges. This type of system employs high-powered floodlights behind tee locations with high angles of elevation to achieve adequate vertical illuminance at each target area. Mounting heights will have little significant influence upon the resultant illumination of the distance markers, and, as the glare to golfers will not be an influencing factor, low mounting heights may be used.", "structuredTables": [{"columns": ["Parameter", "Class III"], "rows": [["Tee · Horizontal illuminance · Eav (lux)", "100"], ["Tee · Uniformity · Emin/Eav", "0.8"], ["Distance marker (+1 m AGL) · Vertical illuminance · Evav (lux)", "50"], ["Colour rendering index · Ra", "20"]]}]}, {"id": "lg4-3-27", "name": "Greyhound racing", "section": "3.27", "page": 28, "tables": ["Class                                   Horizontal illuminance                                          Colour\n                             Race track                         Central field                         rendering\n                    Eav (lx)           Emin/Eav          Eav (lx)           Emin/Eav                    index\nI                    300                   0.7                   50                  0.5                   60\nII                   100                   0.5                   50                  0.5                   60"], "notes": ["Note 1: The vertical illuminance at the finishing line should be 1000 lux for photo-finish equipment and officials.", "Note 2: Recommended minimum mounting heights are 5 m for low-mounting and 10 m for high-mounting systems."], "installation": "This section deals only with track lighting in greyhound stadia. The general lighting of stadia is described in sections 5 and 7. Spectators must be able to identify the individual dogs clearly throughout a race. This may prove difficult when greyhounds are racing on the opposite side of the track due to long viewing distances and inner-rail obstructions that may impair spectator vision. It is therefore important to provide adequate vertical illuminance on inwardly directed surfaces of the track facing the spectators. The lighting should be confined to the track in order to enhance the viewing spectacle. Additional general lighting may be necessary to illuminate the central stadium area if used by officials for presentations and to parade the greyhounds. For economic reasons it is advisable to install track lighting that may be switched to a lower illuminance during the intervals between races. There are two main types of lighting systems generally used for illuminating greyhound tracks.", "structuredTables": [{"columns": ["Parameter", "Class I", "Class II"], "rows": [["Race track · Horizontal illuminance · Eav (lux)", "300", "100"], ["Race track · Uniformity · Emin/Eav", "0.7", "0.5"], ["Central field · Horizontal illuminance · Eav (lux)", "50", "50"], ["Central field · Uniformity · Emin/Eav", "0.5", "0.5"], ["Colour rendering index · Ra", "60", "60"]]}]}, {"id": "lg4-3-28", "name": "Gymnastics", "section": "3.28", "page": 29, "tables": ["Class                                 Horizontal illuminance                                  Colour rendering\n                               Eav (lx)                    Emin/Eav                                index\nI                               500                                 0.7                                 60\nII                              300                                 0.6                                 60\nIII                             200                                 0.5                                 20"], "notes": ["Note 1: Safety lighting (see section 2.8.2.1). Lighting level for the safe stopping of an event is 5% of that for a particular class for a minimum of 30 s."], "installation": "Gymnastics consists of a range of exercises carried out on various types of apparatus: vaulting horse, pommel horse, parallel bars, asymmetric bars, beam, rings and floor. However, for training purposes these pieces of equipment are often used in conjunction with aids such as safety pits, floor mats, trampolines etc. Gymnastics competitions generally take place in large multi-use sports halls or arenas (see sections 4 and 6). Lighting is required to allow the participants to perform precise, accurate movements on all the apparatus, and to allow spectators and judges to follow the action during competition. Suitable illumination is usually provided by luminaires located at high level over the whole activity area, with due allowance for particular apparatus that involve activity at considerable distances above the floor (rings, bars etc). Glare should be minimised by the careful selection and location of luminaires, and light-coloured ceilings are usually preferred to prevent the light source from producing too much contrast with the background.", "structuredTables": [{"columns": ["Parameter", "Class I", "Class II", "Class III"], "rows": [["Horizontal illuminance · Eav (lux)", "500", "300", "200"], ["Uniformity · Emin/Eav", "0.7", "0.6", "0.5"], ["Colour rendering index · Ra", "60", "60", "20"]]}]}, {"id": "lg4-3-29", "name": "Handball (indoor)", "section": "3.29", "page": 30, "tables": ["Class                                 Horizontal illuminance                                  Colour rendering\n                               Eav (lx)                    Emin/Eav                                index\nI                               750                                 0.7                                 60\nII                              500                                 0.7                                 60\nIII                             200                                 0.5                                 20"], "notes": [], "installation": "Most handball courts are defined on a multi-use playing surface (see section 4) which may also be marked out for basketball, volleyball or badminton. The lighting installation must allow players quickly to discern the court markings and follow the fast movement of the small ball and other players. An acceptable lighting installation can usually be provided by luminaires mounted above the court and spaced to meet uniformity requirements. Glare should be minimised by careful control of the brightness contrast between the luminaires and ceiling.", "structuredTables": [{"columns": ["Parameter", "Class I", "Class II", "Class III"], "rows": [["Horizontal illuminance · Eav (lux)", "750", "500", "200"], ["Uniformity · Emin/Eav", "0.7", "0.7", "0.5"], ["Colour rendering index · Ra", "60", "60", "20"]]}]}, {"id": "lg4-3-30", "name": "Hockey (indoor)", "section": "3.30", "page": 30, "tables": ["Class                                 Horizontal illuminance                                  Colour rendering\n                               Eav (lx)                    Emin/Eav                                index\nI                               750                                 0.7                                 60\nII                              500                                 0.7                                 60\nIII                             300                                 0.7                                 20"], "notes": [], "installation": "Keep court markings and the fast-moving ball clearly visible. Space ceiling luminaires for uniformity and limit brightness contrast between the luminaires and ceiling.", "structuredTables": [{"columns": ["Parameter", "Class I", "Class II", "Class III"], "rows": [["Horizontal illuminance · Eav (lux)", "750", "500", "300"], ["Uniformity · Emin/Eav", "0.7", "0.7", "0.7"], ["Colour rendering index · Ra", "60", "60", "20"]]}]}, {"id": "lg4-3-31", "name": "Hockey (outdoor)", "section": "3.31", "page": 30, "tables": ["Class                  Horizontal illuminance                          Glare              Colour rendering\n                     Eav (lx)            Emin/Eav                      rating                  index\nI                     500                       0.7                      50                        60\nII                    300                       0.7                      50                        60\nIII                   200                       0.7                      55                        20"], "notes": ["Note 1: The FIH and national hockey governing bodies may require particular specifications for competition and international provision."], "installation": "Hockey is a visually demanding sport due to the combination of fast action and small ball. As a consequence, the illuminances necessary to participate and follow play are greater than with most other exterior ball sports. A high level of illuminance uniformity is necessary in both horizontal and vertical planes to prevent adaptation problems for players, officials and spectators at all levels of play. The game is played primarily at ground level. The lighting must minimise shadowing, enabling the ball to remain in view at all times. Particular attention should be paid to providing low-glare, uniform lighting within goal areas, along goal lines and at corner locations. This is to ensure good visual conditions for goalkeepers relative to set plays (corners, half corners, free hits and penalties). Lighting masts should not be located in line with the goal-line axes (±10°). End-mast positions should preferably be located outside the intersection of side and goal lines to minimise corner shadows. There must be an obstacle-free zone extending 5 m beyond the goal lines and 4 m beyond the sidelines, within which masts must not be located. Various lighting systems may be suitable for hockey grounds and stadia (see sections 5.1 and 5.2). Owing to the possibility of large spectator attendance, it is important to consider the requirements for emergency lighting (see section 2.8).", "structuredTables": [{"columns": ["Parameter", "Class I", "Class II", "Class III"], "rows": [["Horizontal illuminance · Eav (lux)", "500", "300", "200"], ["Uniformity · Emin/Eav", "0.7", "0.7", "0.7"], ["Glare rating · GR", "50", "50", "55"], ["Colour rendering index · Ra", "60", "60", "20"]]}]}, {"id": "lg4-3-32", "name": "Horse racing (gallop and trotting)", "section": "3.32", "page": 31, "tables": ["Class       Horizontal                     Vertical illuminance                                Glare Colour\n           illuminance            Home stretch          Back stretch and turn                  rating rendering\n         Eav (lx) Emin/Eav Evav (lx)     Evmin/Evav    Evav (lx)    Evmin/Evav                          index\n                                     Length Cross                Length Cross\nI       200           0.6       750        0.6        0.4       500         0.6       0.4        50         60\nII      100           0.4       300        0.6        0.4       200         0.6       0.4        50         60\nIII      50           0.2       100        0.3         -         -           -         -         55         20"], "notes": ["Note 1: The vertical illuminance at the finishing line should be 1000 lux for photo-finish equipment and officials.", "Note 2: For equine safety the lighting level for the safe stopping of an event is 10% of that for a particular class for a minimum of 120 s.", "Note 2: When horses are under observation (by vets for instance), the Eav (horizontal illuminance) should be at least 100 lux."], "installation": "Horse racing is a sport with large spectator provision, usually via one or more grandstands situated along the home straight and opposite the finish line. Floodlighting provision for racing will probably have a requirement for CTV coverage that can be switched to a competitive racing level for non-televised occasions. The lighting is principally confined to the width of track, with spill light adequate to provide supplementary lighting of adjacent areas. Lighting for the paddock and observation areas may utilise lower illuminances than those necessary for racing. Horses are sensitive to variations in lighting levels and are known to act erratically and irrationally when confronted with large variations in luminance uniformity. In extreme cases poor lighting uniformity may cause confusion and could be dangerous during racing. It has been known for horses to attempt to jump prominent bands of luminance over the track during racing, with potentially disastrous results. Visual conditions during racing are therefore of prime importance for both horses and spectators. For horses the lighting must provide a uniformly lit track (longitudinally and crosswise) with gradual transition zones of horizontal illuminance between the back straight and the bends, home straight and finish lines. For spectators the lighting should illuminate the vertical-facing sides of the horses and jockeys at all times whilst ensuring minimal visual intrusion from floodlighting-support structures. The finishing line will require specialist lighting for photo-finish cameras, often incorporating mirror systems to allow the finish to be viewed from both sides of the track simultaneously. Twin-track courses (all-weather and grass tracks) may require separate switching facilities to allow the full racing programme to be accommodated. Very large sporting venues will require a large lighting load. It is therefore essential to consider the environmental impact of floodlighting proposals throughout the lighting design process. Horse racing gallop tracks provide some of the largest floodlit sporting venues. As a consequence it is generally necessary to utilise high-mast structures to carry the large number of floodlights and achieve large spacing between lighting points. The use of high masts will also allow greater offset distances to the track, necessary to ensure an unimpeded view of the home straight during racing and minimal visual intrusion of the back straight and bends.", "structuredTables": [{"columns": ["Parameter", "Class I", "Class II", "Class III"], "rows": [["Horizontal illuminance · Eav (lux)", "200", "100", "50"], ["Uniformity · Emin/Eav", "0.6", "0.4", "0.2"], ["Home stretch · Vertical illuminance · Evav (lux)", "750", "300", "100"], ["Home stretch · Vertical uniformity, length", "0.6", "0.6", "0.3"], ["Home stretch · Vertical uniformity, cross", "0.4", "0.4", "-"], ["Back stretch / turn · Vertical illuminance · Evav (lux)", "500", "200", "-"], ["Back stretch / turn · Vertical uniformity, length", "0.6", "0.6", "-"], ["Back stretch / turn · Vertical uniformity, cross", "0.4", "0.4", "-"], ["Glare rating · GR", "50", "50", "55"], ["Colour rendering index · Ra", "60", "60", "20"]]}]}, {"id": "lg4-3-33", "name": "Hurling", "section": "3.33", "page": 33, "tables": ["Class                   Horizontal illuminance                             Glare              Colour rendering\n                      Eav (lx)            Emin/Eav                         rating                  index\nI                       500                       0.7                        50                         60\nII                      300                       0.7                        50                         60\nIII                     200                       0.5                        55                         20"], "notes": ["Note 1: The Gaelic Athletic Association may require particular specifications for competition and international provision."], "installation": "Hurling is a visually demanding sport due to the combination of fast action and small ball. As a consequence the illuminances necessary to participate and follow play are greater than with most other exterior ball sports. A high level of illuminance uniformity is necessary in both horizontal and vertical planes to prevent adaptation problems for players, officials and spectators at all levels of play. As the ball may be carried or struck on the ground or in the air, the lighting should ensure that the full flight of the ball is visible while minimising shadowing. Particular attention should be paid to providing low-glare, uniform lighting within goal areas, along goal lines and at corner locations. This is to ensure good visual conditions for goalkeepers during set plays. Lighting masts should not be located in line with the goal line axes (±10°). End-mast positions should preferably be located outside the intersection of side and goal lines to minimise corner shadows. Various lighting systems may be suitable for hurling grounds and stadia (see sections 5.1 and 5.2). Owing to the possibility of large spectator attendance it is important to consider the requirements for emergency lighting (see section 2.8). Obtrusive light limitations will need to be considered if planning consent is required (see section 2.10.1).", "structuredTables": [{"columns": ["Parameter", "Class I", "Class II", "Class III"], "rows": [["Horizontal illuminance · Eav (lux)", "500", "300", "200"], ["Uniformity · Emin/Eav", "0.7", "0.7", "0.5"], ["Glare rating · GR", "50", "50", "55"], ["Colour rendering index · Ra", "60", "60", "20"]]}]}, {"id": "lg4-3-34", "name": "Ice hockey", "section": "3.34", "page": 33, "tables": ["Class                                Horizontal illuminance                                               Colour\n                       Indoor ice hockey(note 1)        Outdoor ice hockey                              rendering\n                    Eav (lx)         Emin/Eav         Eav (lx)        Emin/Eav                            index\nI                     750                   0.7                  750                   0.7                   60\nII                    500                   0.7                  500                   0.7                   60\nIII                   300                   0.5                  200                   0.5                   20"], "notes": ["Note 1: Heights below 8 m, Emin/Emax ≥ 0.5. For class III the uniformity can be relaxed to 0.5.", "Note 2: Safety lighting (see section 2.8.2.1). The lighting level for the safe stopping of an event is 5% of that for a particular class for a minimum of 30 s."], "installation": "A high standard of lighting is required as the small, black and fast-moving puck has to be made to contrast against the ice rink so that the spectators and players can see it. This is especially true where there is a large distance between the ice and the spectators, such as in arenas or halls. As ice acts as a good diffuse reflector there should be no strong patterns of light that could distract from the game. Good lighting uniformity is important for seeing the puck. Also, the illumination of the spectator area should be an average of at least 30% of that of the rink in order to limit visual fatigue for spectators and players. An acceptable lighting installation can be provided by luminaires mounted in a regular array over the arena. Side lighting can improve the vertical illuminance on skaters and give improved spectator viewing. Glare control is relatively easy to achieve as the main direction of view is below the horizontal plane. Care needs to be taken in the selection and location of luminaires so that direct glare is minimised. Suitable louvres and screening can prove to be effective in limiting the glare. The ceiling reflectance needs to be high to reduce the luminance contrast compared with the ice rink surface. This is achieved by ensuring that the reflectance of the ceiling is at least 60%.", "structuredTables": [{"columns": ["Parameter", "Class I", "Class II", "Class III"], "rows": [["Indoor · Horizontal illuminance · Eav (lux)", "750", "500", "300"], ["Indoor · Uniformity · Emin/Eav", "0.7", "0.7", "0.5"], ["Outdoor · Horizontal illuminance · Eav (lux)", "750", "500", "200"], ["Outdoor · Uniformity · Emin/Eav", "0.7", "0.7", "0.5"], ["Colour rendering index · Ra", "60", "60", "20"]]}]}, {"id": "lg4-3-35", "name": "Ice sports (artistic)", "section": "3.35", "page": 34, "tables": ["Class                                 Horizontal illuminance                                  Colour rendering\n                               Eav (lx)                    Emin/Eav                                index\nI                               750                                 0.7                                 60\nII                              500                                 0.7                                 60\nIII                             300                                 0.7                                 20"], "notes": ["Note 3: Safety lighting (see section 2.8.2.1). The lighting level for the safe stopping of an event is 5% of that for a particular class for a minimum of 30 s."], "installation": "A high standard of lighting is required for artistic ice sports to ensure that the judges can see the fine detail and movement clearly. This is especially true where there is a large distance between the ice and the spectators, such as in arenas or halls. The ice acts as a good diffuse reflector. There should not be a strong patterns of light that could be distracting. An acceptable lighting installation can be provided by luminaires being mounted in a regular array over the rink. Glare control is relatively easy to achieve as the main direction of view is below the horizontal plane. Care needs to be taken in the selection and location of luminaires so that direct glare is minimised. Suitable louvres and screening can prove to be effective in limiting the glare. The ceiling reflectance needs to be high to reduce the luminance contrast compared with the ice rink surface. This is achieved by ensuring that the reflectance of the ceiling is at least 60%.", "structuredTables": [{"columns": ["Parameter", "Class I", "Class II", "Class III"], "rows": [["Horizontal illuminance · Eav (lux)", "750", "500", "300"], ["Uniformity · Emin/Eav", "0.7", "0.7", "0.7"], ["Colour rendering index · Ra", "60", "60", "20"]]}]}, {"id": "lg4-3-36", "name": "Lawn tennis (indoor)", "section": "3.36", "page": 34, "tables": ["Class                    Horizontal illuminance over principal area                          Colour rendering\n                             Eav (lx)                   Emin/Eav                                  index\nI                               750                                0.7                                 60\nII                              500                                0.7                                 60\nIII                             300                                0.5                                 20"], "notes": ["Note 1: No luminaires should be positioned in that part of the ceiling directly above the principal area.", "Note 2: The reflectance values of court-side fabrics should not be greater than 0.5 for walls and 0.6–0.9 for ceilings. Background colours of blue and green are preferable (see Figures 1 and 2).", "Note 3: The LTA has specific requirements for illuminances over the total playing area and the principal area (see section 2.6)."], "installation": "Keep the fast-moving tennis ball visible against a consistent background. Avoid bright sources in player sightlines. Extend luminaire rows along the sidelines beyond the baseline to light approaching balls and court ends.", "structuredTables": [{"columns": ["Parameter", "Class I", "Class II", "Class III"], "rows": [["Horizontal illuminance · Eav (lux)", "750", "500", "300"], ["Uniformity · Emin/Eav", "0.7", "0.7", "0.5"], ["Colour rendering index · Ra", "60", "60", "20"]]}]}, {"id": "lg4-3-37", "name": "Lawn tennis (outdoor)", "section": "3.37", "page": 35, "tables": ["Class          Horizontal illuminance over principal area                Colour rendering                   Glare\n                     Eav (lx)              Emin/Eav                           index                         rating\nI                        500                          0.7                         60                          50\nII                       300                          0.7                         60                          50\nIII                      200                          0.6                         20                          55"], "notes": ["Note 1: No luminaires should be positioned over the principal area. Note 2. The LTA has specific requirements for illuminances over the total playing area and the principal area (see section 2.11)."], "installation": "The primary visual requirements in tennis are for the players, match officials and any spectators to see both the ball and the court together with its associated markings. It is important that a player does not suffer from disability glare when serving or following a ball. The type of light source and positioning of luminaires should be considered during the design process. For the playing of tennis under floodlights the reflectance of the court surface is significant. The characteristics of the surface material of the court are of importance when considering floodlighting systems. Sharp cut-off luminaires are preferable for tennis court floodlighting, the benefits of which include accurate light output control, a restriction in light overspill and a reduction in direct glare for the players. Columns should be positioned so that participants are unlikely to collide with them.", "structuredTables": [{"columns": ["Parameter", "Class I", "Class II", "Class III"], "rows": [["Horizontal illuminance · Eav (lux)", "500", "300", "200"], ["Uniformity · Emin/Eav", "0.7", "0.7", "0.6"], ["Colour rendering index · Ra", "60", "60", "20"], ["Glare rating · GR", "50", "50", "55"]]}]}, {"id": "lg4-3-38", "name": "Martial arts (including aikido, judo, karate, kendo etc)", "section": "3.38", "page": 35, "tables": ["Class                                Horizontal illuminance                                   Colour rendering\n                              Eav (lx)                    Emin/Eav                                 index\nI                               750                                0.7                                  60\nII                              500                                0.7                                  60\nIII                             200                                0.5                                  20"], "notes": [], "installation": "The speed of action in martial arts is often extremely high. This activity involves varying positions and speed of movement around the floor or activity area. Participants must be able quickly to discern the opponent’s movements, gauge or make attacks and perform throws without glare from the lighting installation. The contrast between the ceiling and luminaires should also be low to eliminate distraction. The type of light source and positioning of luminaires should be considered during the design process.", "structuredTables": [{"columns": ["Parameter", "Class I", "Class II", "Class III"], "rows": [["Horizontal illuminance · Eav (lux)", "750", "500", "200"], ["Uniformity · Emin/Eav", "0.7", "0.7", "0.5"], ["Colour rendering index · Ra", "60", "60", "20"]]}]}, {"id": "lg4-3-39", "name": "Netball", "section": "3.39", "page": 36, "tables": ["Class                      Horizontal illuminance                                      Glare              Colour\n                     Outdoor                        Indoor(note 1)                     rating(note 2)   rendering\n             Eav (lx)       Emin/Eav       Eav (lx)         Emin/Eav                                      index\nI           500                  0.7               750                0.7                50                  60\nII          200                  0.6               500                0.7                50                  60\nIII          75                  0.5               200                0.5                55                  20"], "notes": ["Note 1: No luminaires should be located in that area of the ceiling above a 4 m diameter circle around the baskets.", "Note 2: For outdoor courts."], "installation": "Balance court visibility with glare control when players look upwards. For outdoor netball, avoid floodlights behind the end-of-court D areas. Indoor luminaires should not sit above the 4 m diameter circle around each basket.", "structuredTables": [{"columns": ["Parameter", "Class I", "Class II", "Class III"], "rows": [["Outdoor · Horizontal illuminance · Eav (lux)", "500", "200", "75"], ["Outdoor · Uniformity · Emin/Eav", "0.7", "0.6", "0.5"], ["Indoor · Horizontal illuminance · Eav (lux)", "750", "500", "200"], ["Indoor · Uniformity · Emin/Eav", "0.7", "0.7", "0.5"], ["Glare rating · GR", "50", "50", "55"], ["Colour rendering index · Ra", "60", "60", "20"]]}]}, {"id": "lg4-3-40", "name": "Rugby (league and union)", "section": "3.40", "page": 36, "tables": ["Class                   Horizontal illuminance                              Glare             Colour rendering\n                      Eav (lx)            Emin/Eav                          rating                 index\nI                      500                        0.7                        50                         60\nII                     200                        0.6                        50                         60\nIII                    75                         0.5                        55                         20"], "notes": ["Note 1: The RFU and IRFB may require particular specifications for competition and international provision."], "installation": "Illuminate the full pitch and the flight of the ball for players, officials and spectators. Coordinate mast locations with stands and goalposts to control shadows and avoid obstructing spectator views.", "structuredTables": [{"columns": ["Parameter", "Class I", "Class II", "Class III"], "rows": [["Horizontal illuminance · Eav (lux)", "500", "200", "75"], ["Uniformity · Emin/Eav", "0.7", "0.6", "0.5"], ["Glare rating · GR", "50", "50", "55"], ["Colour rendering index · Ra", "60", "60", "20"]]}]}, {"id": "lg4-3-41", "name": "Shooting (indoor)", "section": "3.41", "page": 37, "tables": ["Class            Horizontal                         Vertical illuminance on target                       Colour\n                illuminance                  Outdoor ranges              Indoor ranges                 rendering\n                at firing line                                       25 m dist. 50 m dist.               index\n            Eav (lx)      Emin/Eav         Evav (lx)     Evmin/Evav   Evav (lx)   Evmin/Evav\nI         200                 0.5            750             0.8           1000              2000           60\nII        200                 0.5            750             0.8           1000              2000           60\nIII       200                 0.5            750             0.8           1000              2000           60"], "notes": ["Source clarification: the supplied page 37 prints 2000 under the 50 m indoor target column, with an Evmin/Evav heading. This heading/value is ambiguous; clarify it before using that entry. The printed value has been preserved here."], "installation": "Participants must be able to observe the targets from various distances and identify target markings. For fixed target shooting, a high and uniform illuminance should be provided at the target with low-level illumination over the firing position. To focus attention on the target it may be preferable to provide a high contrast between target and background. Luminaires should be positioned in such a manner as to avoid impact from bullets and pellets.", "structuredTables": [{"columns": ["Parameter", "Class I", "Class II", "Class III"], "rows": [["Firing line · Horizontal illuminance · Eav (lux)", "200", "200", "200"], ["Firing line · Uniformity · Emin/Eav", "0.5", "0.5", "0.5"], ["Outdoor target · Vertical illuminance · Evav (lux)", "750", "750", "750"], ["Outdoor target · Vertical uniformity · Evmin/Evav", "0.8", "0.8", "0.8"], ["Indoor target at 25 m · Vertical illuminance · Evav (lux)", "1000", "1000", "1000"], ["Indoor target at 50 m · value as printed", "2000", "2000", "2000"], ["Colour rendering index · Ra", "60", "60", "60"]]}]}, {"id": "lg4-3-42", "name": "Skiing (artificial slopes)", "section": "3.42", "page": 37, "tables": ["Class                                Horizontal illuminance                                              Colour\n                         Outdoor slopes                     Indoor slopes                              rendering\n                    Eav (lx)         Emin/Eav         Eav (lx)         Emin/Eav                          index\nIII                   100                  0.5                   300                   0.5                  60"], "notes": ["Note 1: Illuminance is taken on the track for both horizontal and inclined surfaces.", "Note 2: Safety lighting (see section 2.8). The lighting level for the safe stopping of an event is 10% of that for the particular class for a minimum of 30 s.", "Note 3: For artificial snow-covered indoor slopes, illuminances may be reduced due to increased reflection off the slope surface."], "installation": "The lighting must enable skiers safely to negotiate the full length of the artificial ski slope. The general contours of the slope, depressions and surface irregularities must remain recognisable. On long ski runs, the skier may be travelling at high speed. Therefore the lighting must allow quick recognition of changes in slope or incline. The position of floodlights must not provide the skier with a false impression of the route of the ski run. Illumination is generally provided from floodlights positioned along both sides of the slope and aimed both across and down it. This should result in low glare and minimal distraction to descending skiers. Bright light sources that might distract attention should not be visible to skiers while descending the slope. The lighting should also provide for safe ascent of the slope by drag lifts or alternative facilities. Outdoor ski slopes are usually illuminated from columns of low-mounting height above the immediate slope. They provide a larger effective mounting height once the slope itself is taken into account. Indoor ski slopes are generally illuminated from luminaires located so as to provide an atmospheric ambience while still allowing details of the slope to be revealed.", "structuredTables": [{"columns": ["Parameter", "Class III"], "rows": [["Outdoor slope · Horizontal illuminance · Eav (lux)", "100"], ["Outdoor slope · Uniformity · Emin/Eav", "0.5"], ["Indoor slope · Horizontal illuminance · Eav (lux)", "300"], ["Indoor slope · Uniformity · Emin/Eav", "0.5"], ["Colour rendering index · Ra", "60"]]}]}, {"id": "lg4-3-43", "name": "Snooker and billiards", "section": "3.43", "page": 37, "tables": ["Class                                 Horizontal illuminance                                   Colour rendering\n                               Eav (lx)                    Emin/Eav                                 index\nI                               750                                 0.8                                 80\nII                              500                                 0.8                                 80\nIII                             500                                 0.8                                 80"], "notes": [], "installation": "The table must be uniformly illuminated so that the players can follow the balls. The lighting should be shadow-free and enable the players to distinguish the colours of the balls. Referees, spectators and participants need good visibility from all directions. Illumination is normally provided by a purpose-built lighting canopy with general lighting provided to the surrounding area. If the event is to be televised (see section 7), it is usual to install a modified overhead system or additional high-intensity lighting.", "structuredTables": [{"columns": ["Parameter", "Class I", "Class II", "Class III"], "rows": [["Horizontal illuminance · Eav (lux)", "750", "500", "500"], ["Uniformity · Emin/Eav", "0.8", "0.8", "0.8"], ["Colour rendering index · Ra", "80", "80", "80"]]}]}, {"id": "lg4-3-44", "name": "Speed skating", "section": "3.44", "page": 38, "tables": ["Class                      Horizontal illuminance                                       Glare             Colour\n                  Indoor track                 Outdoor track                            rating          rendering\n             Eav (lx)       Emin/Eav       Eav (lx)      Emin/Eav                                         index\nI           500                   0.7               500                0.7                50                 60\nII          300                   0.6               200                0.5                55                 60\nIII         200                   0.5               100                0.5                55                 20"], "notes": ["Note 1: Outdoor tracks. For class II the colour rendering index limit can be reduced to 20.", "Note 2: The vertical illuminance at the finishing line should be increased to 1000 lux for photo-finish purposes.", "Note 3: Safety lighting (see section 2.8.2.1). The lighting level for the safe stopping of an event is 5% of that for the appropriate class for a minimum of 30 s."], "installation": "Speed skating may be held on either 400 m tracks or on what are known as short tracks. Short-track skating will usually take place in a multipurpose arena used for other sports. In this case the specific requirements for speed skating should be met in conjunction with recommendations for other sports. The 400 m track will usually have a dedicated facility where only the track area will need to be lit for the participants. An acceptable lighting installation can be provided by luminaires mounted in a regular array over the arena. Side lighting can improve the vertical illuminance on skaters to give improved spectator viewing. Glare control is relatively easy to achieve as the main direction of view is below the horizontal plane. Care needs to be taken in the selection and location of luminaires so that direct glare is minimised. Suitable louvres and screening can prove effective in limiting glare. The ceiling reflectance needs to be high to reduce the luminance contrast when compared with the ice rink surface. This would be achieved by ensuring that the reflectance of the ceiling is at least 60%.", "structuredTables": [{"columns": ["Parameter", "Class I", "Class II", "Class III"], "rows": [["Indoor track · Horizontal illuminance · Eav (lux)", "500", "300", "200"], ["Indoor track · Uniformity · Emin/Eav", "0.7", "0.6", "0.5"], ["Outdoor track · Horizontal illuminance · Eav (lux)", "500", "200", "100"], ["Outdoor track · Uniformity · Emin/Eav", "0.7", "0.5", "0.5"], ["Glare rating · GR", "50", "55", "55"], ["Colour rendering index · Ra", "60", "60", "20"]]}]}, {"id": "lg4-3-45", "name": "Speedway", "section": "3.45", "page": 38, "tables": ["Class                               Horizontal illuminance                                 Glare         Colour\n                       Track                 Pits           Central field                  rating      rendering\n            Eav (lx)           Emin/Eav    Eav (lx)     Eav (lx)     Emin/Eav                            index\nI         400                    0.6         200             100            0.25                50          60\nII        300                    0.6         100             50             0.25                50          60\nIII       150                    0.5         100              50            0.25                55          20"], "notes": ["Note 1: Additional localised lighting may be required for illumination of the finishing line.", "Note 2: Safety lighting (see section 2.8.2.1). The lighting level for the safe stopping of an event is 10% of that for a particular class for a minimum of 60 s."], "installation": "Speedway is a relatively fast-moving sport and consequently the illuminances provided must be sufficient to allow the participants to be able to detect the track ahead, other competitors and any signals (including emergency signals) from race officials The lighting should be sufficient to allow spectators to discern action when the riders are on distant sections of the track whilst not causing a visual distraction to participants. Visual tasks associated with the preparation and maintenance of machines are undertaken in the pits area and this must therefore be lit to a sufficient illuminance. The performance of visual tasks involved in maintenance work in the pits is likely to benefit from the installation of localised lighting that should be suitably shielded from the view of any riders simultaneously racing on the track. Lighting for speedway use is confined to the areas encompassing the track and pits. However, many tracks form part of a multi-sport arena where other sports are played at different times. It is therefore rare to consider the design of lighting for speedway in total isolation. The creation of suitable and sufficient vertical illuminance is particularly important when the riders are on distant sections of the track, and for this reason the location of columns or towers on the inside of a track is not recommended. It is normal practice to restrict the number of columns and towers used for the lighting of speedway tracks since they can increase the likelihood of rider collision and can also obstruct the view for spectators.", "structuredTables": [{"columns": ["Parameter", "Class I", "Class II", "Class III"], "rows": [["Track · Horizontal illuminance · Eav (lux)", "400", "300", "150"], ["Track · Uniformity · Emin/Eav", "0.6", "0.6", "0.5"], ["Pits · Horizontal illuminance · Eav (lux)", "200", "100", "100"], ["Central field · Horizontal illuminance · Eav (lux)", "100", "50", "50"], ["Central field · Uniformity · Emin/Eav", "0.25", "0.25", "0.25"], ["Glare rating · GR", "50", "50", "55"], ["Colour rendering index · Ra", "60", "60", "20"]]}]}, {"id": "lg4-3-46", "name": "Squash (rackets and raquetball)", "section": "3.46", "page": 39, "tables": ["Class                                   Horizontal illuminance                                  Colour rendering\n                                 Eav (lx)                    Emin/Eav                                index\nI                                  750                              0.7                                60\nII                                 500                              0.7                                60\nIII                                300                              0.7                                20"], "notes": ["Note 1: Luminaires running within 1 m of side walls should be avoided.", "Note 2: The recommended reflectance of walls is 0.6–0.8, of ceilings is 0.6–0.8 and of floors is 0.3–0.4."], "installation": "The visual demands for these sports are exacting, primarily because the action is fast and the ball is small in size. The ball must be seen in silhouette against the court surface, which should be fairly bright. The court lines must be clearly visible to players, spectators and markers. In instances where court walls are glazed it is important to ensure that luminaires are positioned so as to reduce reflection on the glass surfaces. It is very important that glare be restricted. Squash courts are often illuminated by ceiling-mounted luminaires positioned in a standard layout. The illumination of fully glazed courts is the subject of specialist design. Ceiling-mounted luminaires should be constructed so as to eliminate the possibility of balls becoming lodged in them. It is essential for impact-resistant covers or guards to be installed on all luminaires in order to prevent damage. The court ceiling should receive some illumination, which may be provided directly by the luminaires aided in all instances by reflection from the side walls.", "structuredTables": [{"columns": ["Parameter", "Class I", "Class II", "Class III"], "rows": [["Horizontal illuminance · Eav (lux)", "750", "500", "300"], ["Uniformity · Emin/Eav", "0.7", "0.7", "0.7"], ["Colour rendering index · Ra", "60", "60", "20"]]}]}, {"id": "lg4-3-47", "name": "Swimming (all activities)", "section": "3.47", "page": 39, "tables": ["Class – swimming/            Horizontal illuminance                Diving                                 Colour\ndiving/racing/                                            (additional requirement)                      rendering\npolo/synchronised          Eav (lx)            Emin/Eav             Eh/Ev                                 index\nI                            500                       0.7                        0.8                        60\nII                           300                       0.7                        0.5                        60\nIII                          200                       0.5                        0.5                        20"], "notes": ["Note 1: Swimming. The above are general requirements only. Special requirements may be needed for individual pools.", "Note 2: Racing and polo. No underwater lighting should be used.", "Note 3: Safety lighting (see section 2.8.2.1). The lighting level for the safe stopping of an event is 5% of that for a particular class for a minimum of 30 s."], "installation": "The main requirement is to ensure the safety of users by providing adequate illumination and control of reflection on the water surface. The control of surface reflection is particularly important to allow staff to deal with any swimmers in difficulty in the pool. With the complex nature of pool design and restrictions on positioning luminaires, it is important that lighting is considered at the earliest stages of design.", "structuredTables": [{"columns": ["Parameter", "Class I", "Class II", "Class III"], "rows": [["Horizontal illuminance · Eav (lux)", "500", "300", "200"], ["Uniformity · Emin/Eav", "0.7", "0.7", "0.5"], ["Diving · Eh/Ev (additional requirement)", "0.8", "0.5", "0.5"], ["Colour rendering index · Ra", "60", "60", "20"]]}]}, {"id": "lg4-3-48", "name": "Table tennis", "section": "3.48", "page": 41, "tables": ["Class                                 Horizontal illuminance(note 1)                          Colour rendering\n                               Eav (lx)                    Emin/Eav                                index\nI                               750                                 0.7                                 60\nII                              500                                 0.7                                 60\nIII                             300                                 0.7                                 20"], "notes": ["Note 1: Taken on the table and over the surrounding floor-level playing area (see section 2.11).", "Note 2: Reflectance: back walls 0.2; side walls 0.4–0.6; ceilings 0.6–0.8", "Note 3: The standard height of a table tennis table is 0.76 m"], "installation": "The small, fast-moving white ball must be clearly visible during flight, which may extend considerably beyond the area of the table. The table area will require a uniform level of illumination. A lower uniform level is generally acceptable over the remaining playing area. Good contrast is necessary to perceive the small ball. To achieve this, the background should be kept relatively dark. Lighting of the surrounding play area should be uniform and to at least 50% of the level on the table. For a small number of fixed table positions it is often preferable to consider individual table illumination from luminaires mounted above and outside the main playing area. In sports halls with a greater number of tables in use, the general illumination must be adequate for the standard of play required. Luminaires should be positioned at high mounting heights and outside the main viewing zone of the players to avoid glare. At mounting heights above 5 m, suitable luminaires containing discharge lamps may be considered.", "structuredTables": [{"columns": ["Parameter", "Class I", "Class II", "Class III"], "rows": [["Horizontal illuminance · Eav (lux)", "750", "500", "300"], ["Uniformity · Emin/Eav", "0.7", "0.7", "0.7"], ["Colour rendering index · Ra", "60", "60", "20"]]}]}, {"id": "lg4-3-49", "name": "Volleyball (indoor)", "section": "3.49", "page": 42, "tables": ["Class                     Horizontal illuminance over principal area                          Colour rendering\n                              Eav (lx)                   Emin/Eav                                  index\nI                               750                                 0.7                                60\nII                              500                                 0.7                                60\nIII                             200                                 0.5                                20"], "notes": ["Note 1: No luminaires should be positioned in the area of the ceiling directly above the net.", "Note 2: See section 2.11 for a definition of the playing area."], "installation": "Most volleyball courts are defined on a multi-use playing surface (see section 4). The lighting installation must allow players quickly to discern the court markings. The action is fast and, although the ball is relatively large, players must be able to follow movement of both the ball and other players. An acceptable installation may be provided for training and recreational purposes by luminaires mounted above the court and spaced to meet uniformity requirements. Glare can be controlled by careful luminance control and by reducing the contrast between luminaires and ceiling.", "structuredTables": [{"columns": ["Parameter", "Class I", "Class II", "Class III"], "rows": [["Horizontal illuminance · Eav (lux)", "750", "500", "200"], ["Uniformity · Emin/Eav", "0.7", "0.7", "0.5"], ["Colour rendering index · Ra", "60", "60", "20"]]}]}, {"id": "lg4-3-50", "name": "Wall climbing", "section": "3.50", "page": 42, "tables": ["Class                                     Vertical illuminance                                Colour rendering\n                              Evav (lx)                       Evmin/Evav                           index\nI                               500                                 0.8                                60\nII                              300                                 0.8                                60\nIII                             200                                 0.8                                20"], "notes": ["Note 1: Safety lighting (see section 2.8.2.1). The lighting level for the safe stopping of an event is 10% of that for a particular class for a minimum of 60 s."], "installation": "This activity involves differing speeds of action and movement on the climbing wall. This action can vary from general climbing or practice to speed climbing. Participants must be able to recognise the various hand holes and undulations on the wall. Illumination should be provided by an overhead array of luminaires providing vertical illuminance on the climbing wall without causing disability glare to the participants. In cases where the climbing wall is adjustable, the lighting installation should be designed to accommodate these changes. For higher standards of competition, luminaires that concentrate most of the light on the vertical surface are suspended over the wall. If the event is to be televised it is usual to install a modified overhead system or additional high-intensity lighting.", "structuredTables": [{"columns": ["Parameter", "Class I", "Class II", "Class III"], "rows": [["Vertical illuminance · Evav (lux)", "500", "300", "200"], ["Vertical uniformity · Evmin/Evav", "0.8", "0.8", "0.8"], ["Colour rendering index · Ra", "60", "60", "20"]]}]}, {"id": "lg4-3-51", "name": "Weight training", "section": "3.51", "page": 42, "tables": ["           Horizontal illuminance                                      Colour rendering\nEav (lx)                               Emin/Eav                             index\n  500                                    0.7                                     60"], "notes": [], "installation": "Participants must be able to concentrate in safety on their training without distraction from the lighting installation. This activity is different from most sports in that there are no principal area layouts owing to the varying nature of weight training rooms and the positioning of equipment. The lighting system must control the possibility of glare within the area so that the participants can take part in the training. Where potentially difficult or hazardous tasks take place, it may be necessary to improve the illumination at that location with the use of additional lighting.", "structuredTables": [{"columns": ["Parameter", "Requirement"], "rows": [["Horizontal illuminance · Eav (lux)", "500"], ["Uniformity · Emin/Eav", "0.7"], ["Colour rendering index · Ra", "60"]]}]}, {"id": "lg4-3-52", "name": "Wrestling", "section": "3.52", "page": 42, "tables": ["Class                        Horizontal illuminance                 Colour rendering\n                      Eav (lx)                    Emin/Eav               index\nI                      750                          0.7                    60\nII                     500                          0.7                    60\nIII                    200                          0.5                    20"], "notes": [], "installation": "As the action takes place at close quarters, the referees, judges, spectators and participants need good visibility from all directions. The lighting installations should be provided from ceiling-mounted luminaires positioned to provide uniform illumination. Wrestling can occasionally take place in multi-use facilities (see section 4).", "structuredTables": [{"columns": ["Parameter", "Class I", "Class II", "Class III"], "rows": [["Horizontal illuminance · Eav (lux)", "750", "500", "200"], ["Uniformity · Emin/Eav", "0.7", "0.7", "0.5"], ["Colour rendering index · Ra", "60", "60", "20"]]}]}];
